# 拉取云端最新代码(设备端, PowerShell 7)
#
# 用法:  pwsh scripts\sync\pull.ps1
# 做什么: 从 GitHub 拉取 exp/stand-place 的最新代码到本目录, 并列出这次更新了哪些文件。
# 会改动: 只更新代码文件(快进式更新); 不重启服务, 不动机械臂, 不碰 logs\ 和本机配置。
#         本机有改动且与云端冲突时会停下不更新, 把提示原样发给云端 Claude 即可。

$ErrorActionPreference = 'Stop'
$Branch = 'exp/stand-place'
$Root = (Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path
Set-Location $Root

function Fail($msg) { Write-Host "[失败] $msg" -ForegroundColor Red; exit 1 }

$cur = (git rev-parse --abbrev-ref HEAD).Trim()
if ($cur -ne $Branch) { Fail "当前分支是 $cur, 不是 $Branch。没有更新。" }

$dirty = @(git status --porcelain --untracked-files=no)
if ($dirty.Count -gt 0) {
    Write-Host "[注意] 本机有 $($dirty.Count) 个已跟踪文件被改过(现场调参/标定产生的属正常):" -ForegroundColor Yellow
    $dirty | Select-Object -First 20 | ForEach-Object { Write-Host "   $_" }
}

$before = (git rev-parse --short HEAD).Trim()
git fetch origin $Branch
if ($LASTEXITCODE -ne 0) { Fail "连不上 GitHub(git fetch 失败)。" }
git merge --ff-only FETCH_HEAD
if ($LASTEXITCODE -ne 0) { Fail "无法更新: 本机改动与云端改动冲突, 或本机有未推送的提交。代码保持原样, 请把以上输出发给云端 Claude。" }
$after = (git rev-parse --short HEAD).Trim()

if ($before -eq $after) {
    Write-Host "[完成] 已经是最新($after), 没有新改动。" -ForegroundColor Green
    exit 0
}

Write-Host ""
Write-Host "这次更新的提交:"
git log --format='   %h %s' "$before..$after"
$files = @(git diff --name-only $before $after)
Write-Host "更新的文件($($files.Count) 个):"
$files | Select-Object -First 40 | ForEach-Object { Write-Host "   $_" }

$svc = @($files | Where-Object { $_ -match '^(services|actions|flows|hardware|storage|vision|tools)/.*\.py$' })
if ($svc.Count -gt 0) {
    Write-Host "[提醒] 更新了服务用到的 .py 文件。常驻服务要重启后才用上新代码(云端 Claude 会告诉你重启哪个)。" -ForegroundColor Yellow
}
Write-Host "[完成] $before → $after" -ForegroundColor Green

