# 会改动: 只在 robot_cell_logs 文件夹里写; 不改代码仓库, 不删 logs\ 里的任何东西, 不动服务和机械臂。
#         单个文件超过 20MB 时只传末尾 20MB(文件名加 .tail)。

param(
    [int]$Days = 2,
    [string]$Note = '',
    [switch]$All
)

$ErrorActionPreference = 'Stop'
$Branch = 'device-logs'
$MaxBytes = 20MB
$Root = (Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path
$LogSrc = Join-Path $Root 'logs'
$Dest = Join-Path (Split-Path $Root -Parent) 'robot_cell_logs'

function Fail($msg) { Write-Host "[失败] $msg" -ForegroundColor Red; exit 1 }

if (-not (Test-Path $LogSrc)) { Fail "找不到日志目录 $LogSrc" }

# ── 1. 准备日志仓库(第一次运行时自动建) ──
if (-not (Test-Path (Join-Path $Dest '.git'))) {
    $url = (git -C $Root remote get-url origin).Trim()
    Write-Host "第一次运行: 建立日志文件夹 $Dest"
    $has = git -C $Root ls-remote --heads origin $Branch
    if ($LASTEXITCODE -ne 0) { Fail "连不上 GitHub。" }
    if ($has) {
        git clone --single-branch --branch $Branch --depth 1 $url $Dest
        if ($LASTEXITCODE -ne 0) { Fail "下载 $Branch 分支失败。" }
    } else {
        git init $Dest | Out-Null
        git -C $Dest symbolic-ref HEAD "refs/heads/$Branch"
        git -C $Dest remote add origin $url
    }
    git -C $Dest config core.autocrlf false
    git -C $Dest config core.quotepath false
    git -C $Dest config core.longpaths true
    foreach ($k in 'user.name', 'user.email') {
        $v = git -C $Root config $k
        if ($v) { git -C $Dest config $k $v }
    }
}

# ── 2. 复制最近改动过的日志 ──
$since = (Get-Date).AddDays(-$Days)
$skipExt = '.jpg', '.jpeg', '.png', '.bmp', '.npy', '.npz', '.exe', '.zip', '.pt', '.flag', '.pid'
$files = @(Get-ChildItem $LogSrc -Recurse -File | Where-Object {
        $_.LastWriteTime -ge $since -and ($All -or ($skipExt -notcontains $_.Extension.ToLower()))
    })
$copied = 0; $tailed = 0
foreach ($f in $files) {
    $rel = $f.FullName.Substring($LogSrc.Length).TrimStart('\', '/')
    $target = Join-Path $Dest $rel
    New-Item -ItemType Directory -Force -Path (Split-Path $target -Parent) | Out-Null
    try {
        # 服务正在写的日志也要能读: 共享读写方式打开
        $in = [System.IO.File]::Open($f.FullName, 'Open', 'Read', 'ReadWrite,Delete')
        try {
            if ($in.Length -gt $MaxBytes) {
                $target = "$target.tail"
                [void]$in.Seek(-$MaxBytes, 'End')
                $tailed++
            }
            $out = [System.IO.File]::Create($target)
            try { $in.CopyTo($out) } finally { $out.Dispose() }
        } finally { $in.Dispose() }
        $copied++
    } catch {
        Write-Host "   [跳过] $rel : $($_.Exception.Message)" -ForegroundColor Yellow
    }
}

# ── 3. 记下这次上传时的代码版本 ──
$codeRev = (git -C $Root rev-parse --short HEAD).Trim()
$codeBranch = (git -C $Root rev-parse --abbrev-ref HEAD).Trim()
$dirty = @(git -C $Root status --porcelain --untracked-files=no)
$now = Get-Date -Format 'yyyy-MM-dd HH:mm:ss'
$info = @(
    "上传时间: $now",
    "代码版本: $codeBranch @ $codeRev",
    "备注: $Note",
    "收集范围: 最近 $Days 天, $copied 个文件(其中 $tailed 个只取末尾 20MB)",
    "本机已跟踪文件的改动($($dirty.Count) 个):"
) + ($dirty | ForEach-Object { "   $_" })
Set-Content -Path (Join-Path $Dest '_upload_info.txt') -Value $info -Encoding utf8

# ── 4. 提交并推送 ──
git -C $Dest add -A
$changed = @(git -C $Dest status --porcelain)
if ($changed.Count -eq 0) { Write-Host "[完成] 没有新的日志内容。" -ForegroundColor Green; exit 0 }
$msg = "日志 $now 代码$codeRev"
if ($Note) { $msg = "$msg $Note" }
git -C $Dest commit -q -m $msg
if ($LASTEXITCODE -ne 0) { Fail "提交失败。" }
git -C $Dest push -u origin $Branch
if ($LASTEXITCODE -ne 0) { Fail "推送失败(网络或权限)。日志已保存在 $Dest, 稍后重跑本命令即可。" }
Write-Host "[完成] 已上传 $copied 个日志文件到 $Branch 分支(代码版本 $codeRev)。" -ForegroundColor Green

