# -*- coding: utf-8 -*-
"""桌面门(2026-09-09): 相机看到的盒是不是"在桌面落料带上". 上苗机出口斜坡也在相机视野里, 盒子刚滑过传感器还在斜坡上时
相机也能看到, 送料确认/识别都曾把它当桌上的盒(臂飞去斜坡上方近拍, 用户目击). 判据(用户定):
  平面: 基座系 y ≥ 出料口(-0.02)−2cm余量, 且在桌面x范围内(±3cm余量), y ≤ 桌远端+3cm
  高度: 盒顶面 ≤ 桌面(0.064)+10cm (斜坡出料口离桌面27cm; 桌上平躺2.2cm/侧立6cm都算"到了", 能不能抓由识别三道门管)
数据来源: 粗定位 cam_point_mm(顶面质心+深度中位) → 手眼 → 基座系.
"""
import math
import numpy as np
from hardware.arm_tool import ARM_TOOL  # noqa: E402  示教器工具名(config/speed_profile.yaml tool.name)

TABLE_Z = 0.064                 # 桌面在基座系高度(桌高0.564−底座0.5, TCP贴桌实测印证)
TABLE_CX, TABLE_CY = -0.9669, 0.1784
TABLE_LEN, TABLE_WID = 0.710, 0.395      # 长沿基座y, 宽沿基座x(桌子偏航≈90°)
Y_OUTLET = -0.02                # 上苗机出料口(桌子系→基座系), 落料带从这里往+y
MARGIN_XY = 0.03
Y_MIN = Y_OUTLET - 0.02
Y_MAX = TABLE_CY + TABLE_LEN / 2 + MARGIN_XY
X_MIN = TABLE_CX - TABLE_WID / 2 - MARGIN_XY
X_MAX = TABLE_CX + TABLE_WID / 2 + MARGIN_XY
Z_TOP_MAX = TABLE_Z + 0.10


def where(P):
    """基座系点 → (在桌上?, 原因). 两层(2026-09-10用户定): ①在落料带范围内(x桌宽内, y从出料口到桌远端; 桌板被上苗机盖住的16cm不算) ②顶面不高于桌面10cm"""
    x, y, z = float(P[0]), float(P[1]), float(P[2])
    if not (X_MIN <= x <= X_MAX and Y_MIN <= y <= Y_MAX):
        return False, "不在落料带范围内(x=%.3f,y=%.3f; 落料带y≥%.2f)" % (x, y, Y_MIN)
    if z > Z_TOP_MAX:
        return False, "顶面过高(z=%.3f>%.3f)" % (z, Z_TOP_MAX)
    return True, "桌上"


def split_instances(arm, r):
    """粗定位结果 r → (桌上实例[(inst, P基座)], 桌外实例[(inst, P, 原因)]). arm用于读TCP做手眼换算"""
    from tools.grasp.pick_one_box import HANDEYE, tcp_mat
    on, off = [], []
    if not r or not r.get("instances"):
        return on, off
    cur = arm.get_tcp_pose_with_tool(tool=ARM_TOOL, wobj="")
    Tc0 = tcp_mat(cur)
    for inst in r["instances"]:
        px = inst["cam_point_mm"]
        P = Tc0 @ HANDEYE @ np.array([px[0] / 1000, px[1] / 1000, px[2] / 1000, 1.0])
        ok, why = where(P)
        (on if ok else off).append((inst, P) if ok else (inst, P, why))
    return on, off


def count_on_table(arm, vision):
    """相机粗定位一次 → 桌上盒数(-1=相机不可用). 送料确认/手动等盒用"""
    if vision is None or arm is None:
        return -1
    try:
        r = vision.coarse()
    except Exception as e:
        return 0 if "视野无盒" in str(e) else -1
    on, off = split_instances(arm, r)
    return len(on)
-----
def detect(arm, vision, dry=False):
    sw = Stopwatch()
    act = "识别"
    poses = yaml.safe_load(open(os.path.join(ROOT, "config", "poses.yaml"), encoding="utf-8"))
    cur_j = arm._cobot.get_actual_joints_position()
    dev = max(abs(x - y) for x, y in zip(cur_j, poses["home"]))
    if dev > 0.05:
        return ActionResult(act, False, "E_NOT_AT_PORT", C.MANUAL, "不在 home 拍照位(最大轴差%.1f°)" % math.degrees(dev),
                            P.NONE, "关节(°): " + " ".join("%.0f" % math.degrees(x) for x in cur_j), sw.s())
    if vision is None:
        return ActionResult(act, False, "E_VISION_OFFLINE", C.FATAL, "视觉服务不在(vision_service.sh start)", P.NONE, "home", sw.s())
    data = {"模式": "仿真干跑(相机真拍, 臂只在仿真里动)" if dry else "真机"}
    # A 粗定位
    try:
        r = vision.coarse()
    except Exception as e:
        if "视野无盒" in str(e):   # 服务把无盒当异常抛; 归到 E_NO_BOX 供流程接送料(2026-09-07)
            return ActionResult(act, False, "E_NO_BOX", C.MANUAL, "视野无盒, 请上料", P.NONE, "home", sw.s(), data)
        return ActionResult(act, False, "E_VISION_ERROR", C.MANUAL, "粗定位失败: %s" % str(e)[:80], P.NONE, "home", sw.s(), data)
    if not r or not r.get("instances"):
        return ActionResult(act, False, "E_NO_BOX", C.MANUAL, "视野无盒, 请上料", P.NONE, "home", sw.s(), data)
    cur = arm.get_tcp_pose_with_tool(tool=ARM_TOOL, wobj="")
    from actions.table_guard import split_instances
    on_tbl, off_tbl = split_instances(arm, r)          # 桌面门(2026-09-09): 斜坡上的盒不算
    if off_tbl:
        data["桌外"] = "; ".join("%s(conf%.2f)" % (why, i["conf"]) for i, _, why in off_tbl)
    if not on_tbl:
        return ActionResult(act, False, "E_NO_BOX", C.MANUAL, "视野有盒但不在桌上(%s), 等落桌/请上料" % off_tbl[0][2], P.NONE, "home", sw.s(), data)
    best = None
    for inst, Pi in on_tbl:
        di = math.hypot(Pi[0] - SCAN_XY[0], Pi[1] - SCAN_XY[1])
        if best is None or di < best[0]:
            best = (di, Pi, inst["conf"])

