def main():
    t0 = time.time()
    cam = Gemini335Camera()
    assert cam.connect() and cam.start(), "[FAIL] 相机"
    time.sleep(0.4)
    seg, est = init_vision()
    color, _ = capture(cam)          # 首帧推理一次: 模型编译预热在启动期付掉
    seg.segment(color)
    from vision.model_config import seg_model_path
    model = seg_model_path()
    print("[视觉服务] 就绪 %.1fs (相机+%s已热) 监听 %s:%d" % (time.time() - t0, model, HOST, PORT), flush=True)
    threading.Thread(target=hang_guard, args=(cam,), daemon=True).start()

    srv = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    srv.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    srv.bind((HOST, PORT))
    srv.listen(2)
    served = 0
    alive = True
    while alive:
        conn, _addr = srv.accept()
        try:
            conn.settimeout(30)
            buf = b""
            while b"\n" not in buf:
                chunk = conn.recv(65536)
                if not chunk:
                    break
                buf += chunk
            req = json.loads(buf.decode("utf-8")) if buf.strip() else {}
            cmd = req.get("cmd", "")
            t1 = time.time()
            try:
                if cmd == "ping":
                    resp = {"ok": True, "uptime_s": round(time.time() - t0, 1),
                            "served": served, "model": model}
                elif cmd == "coarse":
                    c, d = capture(cam)
                    r = coarse_from_frame(c, d, intr_dict(cam), seg)
                    os.makedirs(os.path.join(ROOT, "data"), exist_ok=True)
                    if not r:   # 留底片: 视野无盒时能看相机到底看到了什么(2026-09-07)
                        cv2.imwrite(os.path.join(ROOT, "data", "coarse_fail.jpg"), c)
                    resp = dict(r, ok=True) if r else {"ok": False, "error": "[FAIL] 视野无盒"}
                elif cmd == "snap":   # 快照: 拍一帧落盘, 不识别
                    c, d = capture(cam)
                    os.makedirs(os.path.join(ROOT, "data"), exist_ok=True)
                    p = os.path.join(ROOT, "data", "snap.jpg"); assert cv2.imwrite(p, c), "写图失败 " + p
                    resp = {"ok": True, "path": p}
                elif cmd == "frame":   # 盘点用(2026-09-17): N帧深度取中位(空洞=0)+彩图落盘, 回路径+内参; 相机由本服务独占, 盘点不再停服务自己开相机
                    n = int(req.get("n", 5)); ds = []; c = None
                    c, d = capture(cam)                          # 第一帧走标准取帧(含预热/耐心窗口/流重启自救)
                    dd = d.astype("float32"); dd[dd <= 0] = float("nan"); ds.append(dd)
                    for _ in range(n - 1):                      # 后续帧直接读, 个别失败跳过
                        ok2, c2, d2 = cam.capture()
                        if ok2 and c2 is not None and d2 is not None:
                            c = c2; dd = d2.astype("float32"); dd[dd <= 0] = float("nan"); ds.append(dd)
                    import numpy as _np
                    with _np.errstate(all="ignore"):
                        med = _np.nanmedian(_np.stack(ds), axis=0)
                    med[_np.isnan(med)] = 0.0
                    out = os.path.join(ROOT, "data", "stocktake"); os.makedirs(out, exist_ok=True)
                    pd_, pc_ = os.path.join(out, "frame_depth.npy"), os.path.join(out, "frame_color.jpg")
                    _np.save(pd_, med); cv2.imwrite(pc_, c)
                    resp = {"ok": True, "depth_npy": pd_, "color_jpg": pc_, "intr": intr_dict(cam), "shape": list(med.shape), "frames": n}
                elif cmd == "detect":
                    c, d = capture(cam)
                    run_dir = new_run_dir()
                    faces, meta = faces_from_frame(c, d, intr_dict(cam), seg, est,
                                                   run_dir, req.get("tcp"))
                    resp = {"ok": True, "run_dir": run_dir,
                            "run": os.path.basename(run_dir), "faces": faces, "meta": meta}
                elif cmd == "quit":
                    resp = {"ok": True, "bye": True}
                    alive = False
                else:
                    resp = {"ok": False, "error": "unknown cmd: %r" % cmd}
            except CameraDead as e:  # 相机没救了: 回完这条就退出, 启动器 5s 后换新进程重连(2026-09-14)
                resp = {"ok": False, "error": str(e) + " (服务重启中)"}
                alive = False
                print("[视觉服务] 相机不可恢复, 退出让启动器重启: %s" % e, flush=True)
            except Exception as e:  # 单请求失败不倒服务
                resp = {"ok": False, "error": str(e)}
            served += 1
            print("[视觉服务] #%d %s %.2fs %s" % (served, cmd, time.time() - t1,
                                              "ok" if resp.get("ok") else resp.get("error")), flush=True)
            conn.sendall((json.dumps(resp) + "\n").encode("utf-8"))
        except Exception as e:
            print("[视觉服务] 连接异常: %s" % e)
        finally:
            conn.close()
    srv.close()
    try:
        cam.stop()
    except Exception:
        pass
    print("[视觉服务] 已退出 (uptime %.0fs, served %d)" % (time.time() - t0, served), flush=True)
    os._exit(0 if served >= 0 else 1)   # 相机 SDK 线程可能拖住正常退出, 直接结束进程


