@app.get("/services", response_model=ServicesResp, tags=["服务管理"])
def services_status():
    """四个常驻服务在不在(端口/进程/hold旗)"""
    return _svc_status()


@app.post("/services/{name}/{cmd}", response_model=SvcResult, tags=["服务管理"])
def services_ctl(name: str, cmd: str):
    """起停一个服务: cmd=start|stop|restart. 工作站服务自己只受理 restart(自退出, 循环拉回)"""
    import subprocess
    if name not in [x[0] for x in SVC]: raise HTTPException(404, {"error": "unknown_service", "name": name})
    if cmd not in ("start", "stop", "restart"): raise HTTPException(400, {"error": "bad_cmd", "cmd": cmd})
    if name == "cell":
        if cmd != "restart": raise HTTPException(409, {"error": "self", "detail": "工作站服务不能从接口停自己(它就是这个接口); 用命令行 services\\svc.bat stop cell"})
        if TASKS.running is not None and TASKS.running.state not in ("needs_human", "paused", "finished", "aborted"):
            raise HTTPException(409, {"error": "busy", "task_id": TASKS.running.id})
        def _die():
            time.sleep(0.8); print("[cell] restart requested via /services, exiting, windows service restarts it in ~5s", flush=True); os._exit(0)   # svc_run.bat 不论退出码都以 1 结束 → Wi
        threading.Thread(target=_die, daemon=True).start()
        return {"ok": True, "name": name, "cmd": cmd, "output": "工作站服务 1s 后自退出, Windows 服务约 5s 后拉回; 轮询 /health 等它"}
    env = dict(os.environ, SVC_NOWAIT="1")
    try:
        r = subprocess.run(["cmd", "/c", _SVC_BAT, cmd, name], capture_output=True, text=True, timeout=60, env=env, cwd=ROOT)
        out = (r.stdout or "") + (r.stderr or "")
    except Exception as e:
        raise HTTPException(500, {"error": "svc_failed", "detail": str(e)})
    try: print("[cell] /services %s %s -> %s" % (name, cmd, out.strip().replace("\n", " | ")), flush=True)
    except Exception: pass
    return {"ok": r.returncode == 0, "name": name, "cmd": cmd, "output": out.strip()}


@app.get("/device", response_model=DeviceStatus, tags=["设备状态"])
def device():
    """设备当前状态(只读). 2026-10-23 起取后台缓存(每秒刷新), 毫秒级返回, 不随设备忙闲变慢; age_s = 这份状态是几秒前读的"""
    return _cached_device()

