# 重启常驻服务(普通权限窗口也能用, 2026-11-17)
#
# 用法:  pwsh D:\robot_cell\services\restart.ps1 vision cell      (可写 vision / scan / cell / upper, 一个或几个)
# 为什么: vision/cell/upper 是以系统账户运行的 Windows 服务, 普通权限窗口里 svc.bat restart 杀不掉它们
#         (svc.bat 会显示 killed, 其实没杀, pid 不变)。这里改为请工作站接口(它有系统权限)去重启。
# 会改动: 只重启点名的服务, 不动机械臂; 有任务正在运行时工作站会拒绝重启自己。
# 判决: 每个服务重启前后的 pid 都打印出来; pid 变了 = 真重启了 [PASS], 没变 = [FAIL]。

param([Parameter(ValueFromRemainingArguments = $true)][string[]]$Names)

$Api = 'http://127.0.0.1:8902'
$order = @('vision', 'scan', 'upper', 'cell')        # 工作站最后重启(它是接口本身)
if (-not $Names) { Write-Host "用法: pwsh D:\robot_cell\services\restart.ps1 vision cell"; exit 1 }
$Names = $order | Where-Object { $Names -contains $_ }
if (-not $Names) { Write-Host "[失败] 只认 vision / scan / cell / upper"; exit 1 }

function Pids {
    $r = @{}
    try { (Invoke-RestMethod "$Api/services" -TimeoutSec 15).services | ForEach-Object { $r[$_.name] = $_.pid } } catch {}
    return $r
}
function WaitUp($name, $old, $sec) {
    for ($i = 0; $i -lt $sec; $i += 3) {
        Start-Sleep 3
        $p = (Pids)[$name]
        if ($p -and $p -ne $old) { return $p }
    }
    return (Pids)[$name]
}

$before = Pids
if ($before.Count -eq 0) { Write-Host "[失败] 工作站接口(8902)连不上, 没法代为重启。先看 services\svc.bat status" -ForegroundColor Red; exit 1 }
$bad = 0
foreach ($n in $Names) {
    $old = $before[$n]
    Write-Host "重启 $n (原 pid $old) ..."
    try { $null = Invoke-RestMethod -Method Post "$Api/services/$n/restart" -TimeoutSec 70 }
    catch { Write-Host "  [失败] 接口拒绝: $($_.ErrorDetails.Message)$($_.Exception.Message)" -ForegroundColor Red; $bad++; continue }
    $wait = if ($n -eq 'vision') { 60 } else { 30 }      # 视觉服务要加载模型
    $new = WaitUp $n $old $wait
    if ($new -and $new -ne $old) { Write-Host "  [PASS] $n 已重启: pid $old → $new" -ForegroundColor Green }
    else { Write-Host "  [FAIL] $n 的 pid 没变($old → $new), 可能没重启成功" -ForegroundColor Red; $bad++ }
}
if ($bad) { exit 1 }

