}


def _load():
    cfg = {k: dict(v) for k, v in DEFAULTS.items()}
    if os.path.exists(LOCAL_FILE):
        import yaml
        try:
            user = yaml.safe_load(open(LOCAL_FILE, encoding="utf-8")) or {}
        except Exception as e:                              # 文件写坏了: 宁可用默认值也别让服务起不来, 但要说出来
            print("[本机设置] config/local.yaml 读不了, 用默认值: %s" % e)
            user = {}
        for sec, vals in user.items():
            if isinstance(vals, dict):
                cfg.setdefault(sec, {}).update(vals)
    return cfg


