def feeder_com():
    """上苗机串口: config/local.yaml feeder.com 优先, 没写就用 speed_profile.yaml feeder.com(老位置, 兼容)"""
    if CFG["feeder"].get("com"):
        return str(CFG["feeder"]["com"])
    from actions.speed import knob
    return str(knob("feeder", "com", "COM14"))


def crv_file(name):
    """上位机 CRV 运行目录下的文件(runtime-state.json / application-standalone.properties)"""
    return os.path.join(CRV_DIR, name)


def summary():
    """给体检/控制台看的一行"""
    return "机械臂 %s:%d · 上苗机 %s · CRV %s · 本机设置文件 %s" % (
        ARM_IP, ARM_PORT, CFG["feeder"].get("com") or "(沿用 speed_profile)", CRV_DIR,
        "config/local.yaml" if os.path.exists(LOCAL_FILE) else "无(用默认值)")


if __name__ == "__main__":
    print(summary())

