def _place_stand(arm, suck, slot, pit, dry, sw, act, box_mm=None):
    """立放(tool.rotator=false): 账本 <slot>_stand.json, 位置=(x_mm 横向毫米, 序号, 0), box_mm=[宽,高,厚]这盒的"""
    from tools.grasp.stand_slot import load_stand_config, compute_stand_pit, stand_place_sequence, joint_speed_report, fold_check, fold_limit
    try:
        led, scfg = load_stand_config(slot)
    except FileNotFoundError as e:
        return ActionResult(act, False, "E_NO_LEDGER", C.MANUAL, "无该格口立放账本(先 calib_stand.sh empty+hold): %s" % e, P.HOLDING if not dry else P.NONE, "未动", sw.s())
    try:
        ch, idx, lay = pit if pit else (0, 0, 0)          # 立放: ch 位为横向 x_mm(可为小数)
        p = compute_stand_pit(led, scfg, ch, idx, lay, box_mm=box_mm)
    except AssertionError as e:
        return ActionResult(act, False, "E_PIT_OUT_OF_RANGE", C.MANUAL, str(e).replace("[FAIL] ", ""), P.HOLDING if not dry else P.NONE, "格口悬停点(未动)", sw.s())
    samp = _JointSampler().start() if dry else None
    data = {"坑位": "(x=%+.1f,序号%d)" % (p["x_mm"], idx), "盒尺寸": "%.0fx%.0fx%.0f" % (p["geom"]["W"], p["geom"]["H"], p["geom"]["D"]), "横向/推进": "%+.1f / %.1f mm" % (p["lat_m"] * 1000, p["push_m"] * 1000),
            "贴板z": "%.4f (降%.1fmm)" % (p["z_board"], (p["z_hover"] - p["z_board"]) * 1000), "模式": "仿真干跑" if dry else "真机", "方式": "立放"}
    try:
        front_meas = stand_place_sequence(arm, suck, slot, led, p)     # 拍基准照的格口: 照片量出的队首(mm), 否则 None
    except AssertionError as e:
        if "LOST" in str(e):                                    # 格内发现货物丢失: 空手已回悬停点, 交流程层按丢失规则处置
            if samp: samp.stop()
            return ActionResult(act, False, "E_LOST", C.NONE, str(e).replace("[FAIL] LOST ", ""), P.NONE, "%s悬停点" % slot, sw.s(), data)
        pay, where = P.UNKNOWN, "不明"
        for m, pp, w in _STAND_STEP:
            if m in str(e): pay, where = pp, w; break
        if dry: pay = P.NONE
        if samp: samp.stop()
        state, raw = describe(arm._cobot); data["机器人状态"] = state; data["看门狗"] = getattr(arm, "last_guard_reason", "") or "-"
        estop = (raw and raw[2] in (7, 8, 9)) or (raw and raw[0] == 4)
        return ActionResult(act, False, "E_PLACE_MOTION", C.MANUAL if estop else C.NEED_RESET, "立放中断于: %s" % str(e).replace("[FAIL] ", ""), pay, where, sw.s(), data)
    if samp:
        rec = samp.stop(); data["min|J5|"] = "%.1f°" % min(min(abs(math.degrees(r[5])), abs(180 - abs(math.degrees(r[5])))) for r in rec) if rec else "-"
        data["关节峰速"], _fn = joint_speed_report(rec, slot, "place_x%+.0f" % p["x_mm"])
        if _fn: data["录制"] = os.path.relpath(_fn, ROOT)
        _lim = fold_limit(led); _m, _bad = fold_check(rec, led); data["J3最折"] = "%.1f° (红线 ±%.0f)" % (_m, _lim) if _m is not None else "-"
        if _bad:   # 2026-09-18: 低层靠中柱列肘部折过头 → 小臂压大臂(真机 L6 x=+262 实撞); 干跑先拦, 不给真机
            return ActionResult(act, False, "E_SELF_COLLISION_RISK", C.MANUAL, "干跑 J3 折到 %.1f° 越过自碰撞红线 ±%.0f°(小臂压大臂), 该坑位禁用: 收窄账本极限或改悬停姿态" % (_m, _lim), P.NONE, 
    from actions.vacuum import di4
    data["真空DI4"] = "放置回悬停后%s (应为0)" % di4(arm, dry)
    # 2026-09-21: 放完后这一列的队首前脸就在这盒的推进量处(TCP 定义在吸盘唇边, 吸住的正是盒前脸).
    #   账本存它, 下次盘点只比位置不做"盒数×节距"的乘法 → 误差不随盒数累积. 松手后纸盒回弹 1~3mm, 由盘点实测修正
    # 2026-11-04 用户定: 拍了基准照的格口, 队首用照片**量出来**的值(算出来的值每盒少算 1~4mm, 多盒累积会让盘点误报)
    front = front_meas if front_meas is not None else _front_cam(slot, p["push_m"] * 1000)
    data["队首前脸"] = ("%.1f mm (放完后该列; 基准照实测)" % front) if front_meas is not None else \
        (("%.1f mm (放完后该列; 已折算到相机尺度)" % front) if front is not None else "没量到(基准照这一列无读数), 不回报")
    return ActionResult(act, True, "OK", C.NONE, "已立放到%s, 臂回悬停点" % data["坑位"], P.NONE if dry else P.PLACED, "%s悬停点" % slot, sw.s(), data,
                        front_mm=front)


def place(arm, suck, rot, slot, pit=None, dry=False, box_mm=None):
    """返回ActionResult。不抛异常(硬件断线除外)。tool.rotator=false → 立放分支; box_mm=[宽,高,厚]这盒的(上位机回去处带的), None=格口基准盒"""
