# -*- coding: utf-8 -*-
"""列偏移(相机尺度 → 推进尺度)自动校准表. 2026-11-18 用户定("第 0 盒法").

是什么: 照片量出的队首 front_mm(相机尺度) 和 机械臂推进量(推进尺度) 之间差一个数, 这个数随格口里的横向位置不同(手眼小角度误差 + 画面边缘测距误差).
怎么来: 每新开一列放第 0 盒(顶背板, 位置 = 理论推进量)后照常拍基准照 → 偏移 = 实测队首 − 第 0 盒理论推进量. 全自动, 不用专门流程.
存哪里: config/col_offset/<格口>.json(不进 git, 每台设备一份; 是相机校准值, 不是库存数据). 按横向位置记, ±TOL_MM 内再开新列就覆盖(用最新的).
谁用: tools/grasp/stand_slot.front_correction —— 放第 k 盒推进 = 队首 − 偏移 − 盒厚; 取队首那盒推进 = 队首 − 偏移.

命令行(只读): python tools\\grasp\\col_offset.py [格口]   列出已记的偏移
"""
import json
import os
import sys
import time

ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
DIR = os.path.join(ROOT, "config", "col_offset")
TOL_MM = 12.0             # 同一位置: 横向差在这以内算同一列
SANE_MM = (10.0, 70.0)    # 偏移合理范围(货架 A 22 个格口空格口基准 31~38mm); 超出视为量错, 不记


def _path(slot):
    return os.path.join(DIR, slot + ".json")


def load(slot):
    try:
        return json.load(open(_path(slot), encoding="utf-8")).get("cols") or []
    except Exception:
        return []


def lookup(slot, x_mm):
    """→ 这个横向位置的记录 dict(offset_mm, x_mm, ...) 或 None"""
    best = None
    for c in load(slot):
        d = abs(float(c["x_mm"]) - float(x_mm))
        if d <= TOL_MM and (best is None or d < best[0]):
            best = (d, c)
    return best[1] if best else None


def record(slot, x_mm, front_mm, push0_mm, box_mm=None):
    """放完第 0 盒后调用. → (offset 或 None, 说明). 失败只打印, 不影响放置"""
    try:
        off = float(front_mm) - float(push0_mm)
        if not (SANE_MM[0] <= off <= SANE_MM[1]):
            return None, "第0盒偏移 %.1fmm 不在合理范围 %.0f~%.0f, 不记(可能量错)" % (off, SANE_MM[0], SANE_MM[1])
        cols = [c for c in load(slot) if abs(float(c["x_mm"]) - float(x_mm)) > TOL_MM]
        cols.append({"x_mm": round(float(x_mm), 1), "offset_mm": round(off, 1), "front0_mm": round(float(front_mm), 1),
                     "push0_mm": round(float(push0_mm), 1), "box_mm": box_mm, "time": time.strftime("%Y-%m-%d %H:%M:%S")})
        cols.sort(key=lambda c: c["x_mm"])
        os.makedirs(DIR, exist_ok=True)
        tmp = _path(slot) + ".tmp"
        json.dump({"slot": slot, "note": "第0盒自动校准的列偏移(相机尺度-推进尺度), 见 tools/grasp/col_offset.py", "cols": cols},
                  open(tmp, "w", encoding="utf-8"), ensure_ascii=False, indent=1)
        os.replace(tmp, _path(slot))
        return off, "记下这一列偏移 %.1fmm(队首 %.1f − 第0盒推进 %.1f)" % (off, float(front_mm), float(push0_mm))
    except Exception as e:
        return None, "记列偏移失败(不影响放置): %s" % e


if __name__ == "__main__":
    slots = sys.argv[1:] or sorted(f[:-5] for f in os.listdir(DIR) if f.endswith(".json")) if os.path.isdir(DIR) else sys.argv[1:]
    if not slots:
        print("还没有任何格口记过列偏移(新开一列放第 0 盒后自动记)")
    for s in slots:
        cs = load(s)
        print("%s: %d 列" % (s, len(cs)))
        for c in cs:
            print("  x=%+7.1f  偏移 %.1fmm  (队首 %.1f − 推进 %.1f, %s)" % (c["x_mm"], c["offset_mm"], c["front0_mm"], c["push0_mm"], c.get("time", "")))

